#pragma once
#include <juce_audio_processors/juce_audio_processors.h>
#include <span>
#include <string_view>

namespace mm
{
enum class ParamType
{
    Float,
    Int,
    Bool,
    Choice
};

// One row of a plugin's parameter table. Generated by tools/gen_params.py in this exact field order.
struct ParamSpec
{
    const char* id;
    const char* name;
    ParamType type;
    const char* unit;
    float min;
    float max;
    float def;
    float skew;
    float smoothingMs;
    int numChoices;
    const char* const* choices;
    const char* group;
    bool ai;
};

using ParamId = const char*;

class ParamTable
{
public:
    explicit ParamTable(std::span<const ParamSpec> specs) : table(specs) {}

    const ParamSpec* find(std::string_view id) const noexcept;
    int index(std::string_view id) const noexcept; // -1 if absent
    std::span<const ParamSpec> specs() const noexcept { return table; }
    int size() const noexcept { return static_cast<int>(table.size()); }

    juce::AudioProcessorValueTreeState::ParameterLayout makeLayout() const;

private:
    std::span<const ParamSpec> table;
};
} // namespace mm
